/**
 * Commercial Leases & ARGUS: reading cash flow and valuation reports (subtopic argus-reports).
 * The report in the document review is generated by the lease engine, so its figures are computed, not typed.
 */
import { formatValue } from '../../../engine/format';
import { projectCashFlow, valuation } from '../../../leases/engine';
import { categoryItems } from '../define';
import { SORRENTO_OFFICE as S } from './scenario';

const cf = projectCashFlow(S.building, S.tenants, S.mla, S.years + 1);
const v = S.valuation!;
const usd = (n: number) => formatValue(n, 'usd');
const pct = (n: number) => formatValue(n, 'pct2');

// What a correct valuation page would show...
const right = valuation(cf, S.years, v);
// ...and the two planted errors: the resale capitalises the FINAL hold year's NOI, and selling costs are added.
const wrongNoi = cf[S.years - 1].noi;
const wrongGross = wrongNoi / v.exitCap;
const wrongNet = wrongGross * (1 + v.saleCost);
const wrongPv = cf.slice(0, S.years).reduce((n, row, i) => n + row.cashFlowBeforeDebt / (1 + v.discount) ** (i + 1), 0) + wrongNet / (1 + v.discount) ** S.years;

export const ITEMS = categoryItems('argus', [
  {
    id: 'argus-reports-order-cash-flow-lines',
    type: 'order',
    level: 2,
    topic: 'argus-reports',
    title: 'Order the lines of a lease-by-lease cash flow',
    prompt: 'A lease-by-lease cash flow report runs from rent at the top to cash flow before debt at the bottom. Put these lines in the order they appear.',
    tags: ['cash flow report', 'NOI', 'below the line'],
    estMinutes: 1.5,
    hints: ['Start with what tenants owe, then what is lost, then what the building costs, then what leasing costs.', 'NOI comes before any leasing or capital cost.'],
    lines: [
      'Base rent',
      'Expense recoveries',
      'Free rent, turnover vacancy, general vacancy and credit loss',
      'Effective gross revenue',
      'Operating expenses',
      'Net operating income',
      'Tenant improvements, leasing commissions and capital reserves',
      'Cash flow before debt',
    ],
    trap: 'Tenant improvements and leasing commissions are not operating expenses. They come AFTER net operating income, which is why NOI can look healthy in a year when cash flow collapses.',
    explanation:
      'Revenue is built up (base rent, recoveries), then reduced by what will not be collected (free rent, vacancy, credit loss) to effective gross revenue. Operating expenses come off to give NOI. Leasing and capital costs are deducted below NOI to reach cash flow before debt.',
  },
  {
    id: 'argus-reports-docreview-valuation-page',
    type: 'docreview',
    level: 2,
    topic: 'argus-reports',
    title: 'Check a valuation page',
    prompt:
      'An analyst prepared this valuation summary for a five-year hold of an office building in Sorrento Mesa (illustrative). The yearly cash flows come straight from the lease-by-lease model and are correct. Flag the lines of the resale and present value calculation that contain a mistake.',
    tags: ['valuation', 'resale', 'exit cap', 'present value'],
    estMinutes: 4,
    hints: [
      'A buyer at the end of year 5 is paying for the income that comes next.',
      'Check which year’s NOI is capitalised, and which way selling costs move the proceeds.',
      'Two things are wrong: the NOI used for the resale, and the treatment of selling costs.',
    ],
    document: {
      kind: 'Valuation summary',
      title: 'Present value, five-year hold (illustrative)',
      columns: ['Line', 'Amount', 'How it was computed'],
      lines: [
        { id: 'flows', text: 'CASH FLOW BEFORE DEBT', heading: true, cells: ['', ''] },
        ...cf.slice(0, S.years).map((row) => ({ id: `year-${row.year}`, text: `Year ${row.year}`, cells: [usd(row.cashFlowBeforeDebt), `NOI ${usd(row.noi)} less leasing costs and reserves`] })),
        { id: 'resale', text: 'RESALE AT THE END OF YEAR 5', heading: true, cells: ['', ''] },
        { id: 'resale-noi', text: 'NOI capitalised', cells: [usd(wrongNoi), 'Year 5 NOI, the last year of the hold'] },
        { id: 'exit-cap', text: 'Exit cap rate', cells: [pct(v.exitCap), 'Assumption'] },
        { id: 'gross-resale', text: 'Gross resale value', cells: [usd(wrongGross), 'NOI capitalised / exit cap rate'] },
        { id: 'net-resale', text: 'Net resale proceeds', cells: [usd(wrongNet), `Gross value plus ${formatValue(v.saleCost, 'pct1')} selling costs`] },
        { id: 'discount', text: 'Discount rate', cells: [pct(v.discount), 'Assumption'] },
        { id: 'pv', text: 'Present value', heading: true, cells: [usd(wrongPv), 'Cash flows and net resale, discounted'] },
      ],
    },
    issues: [
      {
        lines: ['resale-noi', 'gross-resale'],
        label: `The resale should capitalise the NOI of the year AFTER the hold, because that is the income the buyer is paying for: year 6 NOI of ${usd(cf[S.years].noi)}, not year 5.`,
        category: 'timing',
      },
      {
        lines: ['net-resale'],
        label: 'Selling costs reduce what the seller receives. Net proceeds are the gross value LESS selling costs, not plus.',
        category: 'sign',
      },
    ],
    explanation: `Done correctly, the net resale is ${usd(right.resale)} and the present value is ${usd(right.pv)}, against the ${usd(wrongPv)} shown. The resale is usually the largest single number on the page, so its two inputs (which NOI, and the exit cap) deserve the first look.`,
  },
  {
    id: 'argus-reports-numeric-net-resale',
    type: 'numeric',
    level: 2,
    topic: 'argus-reports',
    title: 'Net resale proceeds from the report',
    prompt:
      'A valuation page shows a five-year hold. Year 5 NOI is {noi_five|usd} and year 6 NOI is projected at {noi_six|usd}. The exit cap rate is {exit_cap|pct1} and selling costs are {sale_cost|pct1} of the price. What are the net resale proceeds at the end of year 5? (Illustrative figures.)',
    tags: ['resale', 'exit cap', 'selling costs'],
    estMinutes: 2,
    hints: ['Which year’s income is the buyer paying for?', 'Capitalise the NEXT year’s NOI, then take off selling costs.', 'Net resale = year 6 NOI / exit cap x (1 - selling costs).'],
    vars: [
      { name: 'noi_five', min: 1200000, max: 2200000, step: 20000, format: 'usd' },
      { name: 'growth', choices: [0.02, 0.03, 0.04, 0.05] },
      { name: 'noi_six', formula: '=noi_five*(1+growth)', format: 'usd' },
      { name: 'exit_cap', choices: [0.06, 0.065, 0.07, 0.075], format: 'pct1' },
      { name: 'sale_cost', choices: [0.015, 0.02, 0.025], format: 'pct1' },
    ],
    answer: '=noi_six/exit_cap*(1-sale_cost)',
    format: 'usd',
    mistakes: [
      { formula: '=noi_five/exit_cap*(1-sale_cost)', label: 'That capitalises year 5 NOI. The buyer is paying for the income AFTER the sale, so use year 6.', category: 'timing' },
      { formula: '=noi_six/exit_cap', label: 'That is the gross price. Take off the {sale_cost|pct1} selling costs to get what the seller keeps.', category: 'omitted' },
      { formula: '=noi_six/exit_cap*(1+sale_cost)', label: 'Selling costs come OFF the price. Multiply by (1 - selling costs), not (1 + selling costs).', category: 'sign' },
    ],
    explanation:
      'Gross value = year 6 NOI / exit cap = {noi_six|usd} / {exit_cap|pct1} = {=noi_six/exit_cap|usd}. Less {sale_cost|pct1} selling costs: {=noi_six/exit_cap*(1-sale_cost)|usd}.',
  },
]);
